INSERT INTO product_translations (product_id, language_id, title, description, page_title, page_subtitle, page_description, cta_section_title, cta_section_description, cta_button_text)
VALUES
('7cf28a46-72e0-4130-8864-b9b659b0d35c', 2, 'Findloom', 'Infraestructura de búsqueda de nivel empresarial para e-commerce. Conecta tus feeds XML, potencia tu tienda con búsquedas ultrarrápidas en menos de 50ms. Configúralo en minutos, escala a millones de productos.', 'Findloom | Infraestructura de Búsqueda Ultrarrápida para eCommerce', 'Conecta tus feeds XML, potencia tu tienda con búsquedas ultrarrápidas', 'Findloom es una infraestructura SaaS de búsqueda para e-commerce de nivel empresarial que permite a las tiendas online conectar feeds XML de productos y ofrecer resultados de búsqueda en menos de 50ms entre millones de productos. Con soporte multidominio, tolerancia a errores tipográficos, búsqueda facetada, analíticas en tiempo real y seguridad SOC 2, Findloom transforma la forma en que los compradores descubren productos.', '¿Listo para Transformar la Búsqueda de tu Tienda?', 'Conecta tus feeds XML y comienza a ofrecer resultados de búsqueda ultrarrápidos a tus clientes en minutos.', 'Comenzar Gratis'),
